import {describe, it, expect} from 'vitest';
import {accumulateUsage} from './orchestratorHelpers.js';
import type {UsageMetadata} from '../types/ai.js';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ChatSession} from '../types/session.js';
import {scriptedProvider} from './chatOrchestratorTestSupport.js';

describe('accumulateUsage', () => {
  it('returns undefined when both are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });

  it('returns round usage when total is undefined', () => {
    const round: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    expect(accumulateUsage(undefined, round)).toEqual(round);
  });

  it('returns total usage when round is undefined', () => {
    const total: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    expect(accumulateUsage(total, undefined)).toEqual(total);
  });

  it('sums fields when both are defined', () => {
    const total: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const round: UsageMetadata = {inputTokens: 20, outputTokens: 10, totalTokens: 30};
    expect(accumulateUsage(total, round)).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });
});

describe('ChatOrchestrator multi-round usage', () => {
  const promptBuilder = new PromptBuilder({identity: 'test'});
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };

  const toolRegistry = new ToolRegistry();
  toolRegistry.register({name: 'echo', description: 'echo', inputSchema: {type: 'object'}}, async () => ({
    result: 'echoed',
  }));

  it('accumulates usage across multiple tool rounds', async () => {
    const provider = scriptedProvider([
      [
        {type: 'tool_use', toolCall: {id: 'c1', name: 'echo', input: {}}},
        {
          type: 'stop',
          stopReason: 'tool_use',
          usage: {inputTokens: 100, outputTokens: 10, totalTokens: 110},
        },
      ],
      [
        {type: 'text', text: 'done'},
        {
          type: 'stop',
          stopReason: 'end_turn',
          usage: {inputTokens: 200, outputTokens: 20, totalTokens: 220},
        },
      ],
    ]);

    let reportedUsage: UsageMetadata | undefined;
    const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
      hooks: {
        afterModelResponse: async (_session, _text, usage) => {
          reportedUsage = usage;
        },
      },
    });

    await orchestrator.processMessage(session);

    expect(reportedUsage).toEqual({
      inputTokens: 300,
      outputTokens: 30,
      totalTokens: 330,
    });
  });
});

